/**
 * Creates a new Supabase Client.
 */
export const createClient = <
  Database = any,
  SchemaName extends string & keyof Database = 'public' extends keyof Database
    ? 'public'
    : string & keyof Database,
  Schema extends GenericSchema = Database[SchemaName] extends GenericSchema
    ? Database[SchemaName]
    : any
>(
  supabaseUrl: string,
  supabaseKey: string,
  options?: SupabaseClientOptions<SchemaName>
): SupabaseClient<Database, SchemaName, Schema> => {
  return new SupabaseClient<Database, SchemaName, Schema>(supabaseUrl, supabaseKey, options)
}

serve(async (req) => {
    const { to, subject, body } = await req.json();

    // Send email using Resend API (or other service)
    const emailResponse = await fetch('https://api.resend.com/v1/emails', {
        method: 'POST',
        headers: {
            'Authorization': `Bearer YOUR_RESEND_API_KEY`,
            'Content-Type': 'application/json'
        },
        body: JSON.stringify({
            from: 'your-email@example.com',
            to: to,
            subject: subject,
            html: `<p>${body}</p>`
        })
    });

    return new Response(JSON.stringify(await emailResponse.json()), { status: 200 });
});
